<script setup>
import { computed, reactive, ref, watch } from 'vue'; import { Plus, Search, TrendingUp } from 'lucide-vue-next'; import { useAuthStore } from '@/stores/auth'; import { useFinanceStore } from '@/stores/finance'; import { useMasterDataStore } from '@/stores/masterData'; import { useUiStore } from '@/stores/ui'; import { formatCurrency, formatDate, todayIso } from '@/utils/formatters'; import BaseBadge from '@/components/ui/BaseBadge.vue'; import BaseButton from '@/components/ui/BaseButton.vue'; import BaseCard from '@/components/ui/BaseCard.vue'; import BaseInput from '@/components/ui/BaseInput.vue'; import BaseModal from '@/components/ui/BaseModal.vue'; import BaseSelect from '@/components/ui/BaseSelect.vue'; import BaseTextarea from '@/components/ui/BaseTextarea.vue'; import Pagination from '@/components/ui/Pagination.vue';
const finance=useFinanceStore(),auth=useAuthStore(),ui=useUiStore(),master=useMasterDataStore(),search=ref(''),period=ref('semua'),category=ref('semua'),account=ref('semua'),page=ref(1),modal=ref(false),edit=ref(null),error=ref(''),pageSize=5; const accounts=computed(()=>master.activeRecordsFor('account')); const blank=()=>({date:todayIso(),source:'Lain-lain',category:'',description:'',accountId:'',amount:'',notes:''}); const form=reactive(blank()),readOnly=computed(()=>auth.role==='manager'); const filtered=computed(()=>finance.allIncomes.filter(x=>`${x.description} ${x.invoiceNumber} ${x.client} ${x.source}`.toLowerCase().includes(search.value.toLowerCase())&&(category.value==='semua'||x.category===category.value)&&(account.value==='semua'||x.accountId===account.value))); const rows=computed(()=>filtered.value.slice((page.value-1)*pageSize,page.value*pageSize)),total=computed(()=>filtered.value.reduce((sum,x)=>sum+x.amount,0));watch([search,period,category,account],()=>page.value=1); const accountName=id=>accounts.value.find(x=>x.id===id)?.nama||'-'; const openAdd=()=>{edit.value=null;Object.assign(form,blank());error.value='';modal.value=true};const openEdit=item=>{edit.value=item;Object.assign(form,item,{amount:String(item.amount)});error.value='';modal.value=true};const save=()=>{try{edit.value?finance.updateManualIncome(edit.value.id,form):finance.addManualIncome(form);ui.notify(edit.value?'Pemasukan berhasil diperbarui.':'Pemasukan berhasil ditambahkan.');modal.value=false}catch(e){error.value=e.message}};
</script>
<template><div class="p-6"><header class="mb-5 flex justify-between"><div><h1 class="text-xl font-semibold text-[#172033]">Pemasukan</h1><p class="mt-0.5 text-sm text-[#667085]">Pencatatan seluruh penerimaan kas dan bank perusahaan.</p></div><BaseButton v-if="!readOnly" @click="openAdd"><Plus :size="15"/>Tambah Pemasukan</BaseButton></header><BaseCard class="mb-5 flex justify-between" padding="p-4"><div><p class="text-xs text-[#667085]">Total Pemasukan</p><p class="text-2xl font-bold text-[#16A34A]">{{formatCurrency(total)}}</p></div><TrendingUp :size="32" class="text-green-200"/></BaseCard><div class="mb-4 flex flex-wrap gap-3"><BaseInput v-model="search" class="max-w-xs flex-1" placeholder="Cari pemasukan..."><template #prefix><Search :size="14"/></template></BaseInput><BaseSelect v-model="category" class="w-40" :options="[{value:'semua',label:'Semua Kategori'},'Pendapatan Jasa','Pendapatan Lainnya']"/><BaseSelect v-model="account" class="w-40" :options="[{value:'semua',label:'Semua Rekening'},...accounts.map(x=>({value:x.id,label:x.nama}))]"/></div><section class="overflow-x-auto rounded-lg border border-[#E2E6EC] bg-white"><table class="w-full min-w-[900px]"><thead><tr class="border-b bg-[#F9FAFB]"><th v-for="h in ['Tanggal','Sumber','Kategori','Keterangan','Rekening','Nominal','Aksi']" :key="h" class="px-4 py-3 text-left text-xs text-[#667085]">{{h}}</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id" class="border-b"><td class="px-4 py-3 text-sm">{{formatDate(item.date)}}</td><td class="px-4 py-3"><BaseBadge :variant="item.source==='invoice'?'info':'default'">{{item.source==='invoice'?'Invoice':'Manual'}}</BaseBadge></td><td class="px-4 py-3 text-sm">{{item.category}}</td><td class="px-4 py-3 text-sm">{{item.description}}</td><td class="px-4 py-3 text-sm">{{accountName(item.accountId)}}</td><td class="px-4 py-3 text-right text-sm font-semibold text-green-600">{{formatCurrency(item.amount)}}</td><td class="px-4 py-3"><button v-if="item.source==='manual'&&!readOnly" class="text-xs text-[#315DA8]" @click="openEdit(item)">Edit</button></td></tr></tbody></table><Pagination :page="page" :total="filtered.length" :per-page="pageSize" @change="page=$event"/></section><BaseModal :open="modal" :title="edit?'Edit Pemasukan Manual':'Tambah Pemasukan Manual'" size="xl" @close="modal=false"><div class="space-y-4"><p class="rounded-md border border-amber-200 bg-amber-50 p-3 text-xs text-amber-700">Form ini untuk pemasukan non-invoice. Pembayaran invoice tercatat otomatis melalui Catat Pembayaran.</p><div class="grid grid-cols-1 gap-4 md:grid-cols-2"><BaseInput v-model="form.date" label="Tanggal" type="date" required/><BaseInput v-model="form.amount" label="Nominal (Rp)" type="number" required/><BaseInput v-model="form.source" label="Sumber"/><BaseInput v-model="form.category" label="Kategori" required/><BaseSelect v-model="form.accountId" label="Rekening" :options="[{value:'',label:'Pilih rekening'},...accounts.map(x=>({value:x.id,label:`${x.nama} — ${x.nomor}`}))]"/><div/><BaseTextarea v-model="form.description" class="md:col-span-2" label="Keterangan" required :rows="3"/><BaseTextarea v-model="form.notes" class="md:col-span-2" label="Catatan" :rows="3"/></div><p v-if="error" class="text-sm text-red-600">{{error}}</p></div><template #footer><BaseButton variant="secondary" @click="modal=false">Batal</BaseButton><BaseButton @click="save">Simpan</BaseButton></template></BaseModal></div></template>

<style scoped>
thead tr, tbody tr { border-color: #E2E6EC !important; }
</style>
